"""Pydantic models for synthetic question/SQL dataset records.

See AGENTS.md: "pydantic models for ... dataset records (Example(question, sql,
tags, split))."
"""

from __future__ import annotations

from typing import Literal

from pydantic import BaseModel

DifficultyTag = Literal[
    "single_table",
    "aggregation",
    "join",
    "filter_date_fy",
    "top_n",
    "nested",
    "window",
]

Split = Literal["train", "dev", "test"]


class CandidateExample(BaseModel):
    """One question/SQL pair as generated by the frontier model, pre-execution."""

    question: str
    sql: str
    tags: list[DifficultyTag]
    expects_empty_result: bool = False


class ExecutedExample(CandidateExample):
    """A candidate after being parsed and executed against the silver tables."""

    valid: bool
    row_count: int | None = None
    error: str | None = None


class Example(BaseModel):
    """A final, kept, split-assigned training/eval example."""

    question: str
    sql: str
    tags: list[DifficultyTag]
    split: Split
